object GradeMateColors {
    val Primary = Color.rgb(25, 118, 210)
    val PrimaryDark = Color.rgb(17, 82, 147)
    val Secondary = Color.rgb(102, 187, 106)
    val Background = Color.rgb(245, 245, 245)
    val Surface = Color.rgb(255, 255, 255)
    val TextPrimary = Color.rgb(28, 30, 33)
    val TextSecondary = Color.rgb(92, 101, 112)
    val Border = Color.rgb(225, 228, 232)

    const val Primary25 = "rgba(25, 118, 210, 0.25)"
    const val Border35 = "rgba(225, 228, 232, 0.35)"
    val FooterBackground = Color.rgb(15, 27, 45)
    val TextOnDark = Color.rgb(232, 236, 242)
    val TextOnDarkSecondary = Color.rgb(139, 152, 172)
}

fun Color.toRgba(alpha: Float = 1f): String {
    val rgb = this.toRgb()
    return "rgba(${rgb.red}, ${rgb.green}, ${rgb.blue}, $alpha)"
}
private val ContentMaxWidth = 1120.px

// ---------------------------------------------------------------------------
// Shared / layout styles — base = phone, Breakpoint.MD+ = tablet/desktop
// ---------------------------------------------------------------------------

val SectionStyle = CssStyle {
    base {
        Modifier
            .fillMaxWidth()
            .padding(topBottom = 56.px, leftRight = 20.px)
    }
    Breakpoint.MD {
        Modifier.padding(topBottom = 96.px, leftRight = 32.px)
    }
}

val SectionInnerStyle = CssStyle {
    base {
        Modifier
            .fillMaxWidth()
            .maxWidth(ContentMaxWidth)
            .margin(leftRight = autoLength)
    }
}

// A two-column layout that stacks to one column on phones and becomes a row at MD+.
val ResponsiveRowStyle = CssStyle {
    base {
        Modifier
            .fillMaxWidth()
            .styleModifier {
                property("display", "flex")
                property("flex-direction", "column")
                property("gap", "40px")
            }
    }
    Breakpoint.MD {
        Modifier.styleModifier {
            property("flex-direction", "row")
            property("justify-content", "space-between")
            property("align-items", "center")
            property("gap", "48px")
        }
    }
}

// A responsive card grid: 1 column on phones, 2 on tablets, N on desktop.
private fun gridStyle(desktopColumns: Int) = CssStyle {
    base {
        Modifier.styleModifier {
            property("display", "grid")
            property("grid-template-columns", "1fr")
            property("gap", "20px")
        }
    }
    Breakpoint.SM {
        Modifier.styleModifier { property("grid-template-columns", "repeat(2, 1fr)") }
    }
    Breakpoint.LG {
        Modifier.styleModifier { property("grid-template-columns", "repeat($desktopColumns, 1fr)") }
    }
}

val QuickStartGridStyle = gridStyle(desktopColumns = 4)
val DownloadsGridStyle = gridStyle(desktopColumns = 3)

