val PrimaryButtonStyle = CssStyle {
    base {
        Modifier
            .fillMaxWidth()
            .backgroundColor(GradeMateColors.Primary)
            .color(Colors.White)
            .fontWeight(FontWeight.SemiBold)
            .fontSize(15.px)
            .padding(topBottom = 15.px, leftRight = 26.px)
            .borderRadius(10.px)
            .styleModifier { property("border", "none") }
            .cursor(Cursor.Pointer)
            .styleModifier { property("transition", "background-color 0.18s ease, transform 0.18s ease") }
    }
    Breakpoint.MD {
        Modifier.width(autoLength).padding(topBottom = 14.px, leftRight = 26.px)
    }
    hover {
        Modifier
            .backgroundColor(GradeMateColors.PrimaryDark)
            .styleModifier { property("transform", "translateY(-1px)") }
    }
    focusVisible {
        Modifier.styleModifier {
            property(
                "outline",
                "3px solid rgba(25, 118, 210, 0.35)"
            )
            property("outline-offset", "2px")
        }
    }
}

val SecondaryButtonStyle = CssStyle {
    base {
        Modifier
            .fillMaxWidth()
            .backgroundColor(GradeMateColors.Surface)
            .color(GradeMateColors.TextPrimary)
            .fontWeight(FontWeight.SemiBold)
            .fontSize(15.px)
            .padding(topBottom = 14.px, leftRight = 25.px)
            .borderRadius(10.px)
            .styleModifier {
                property("border", "1px solid #E1E4E8")
            }
            .cursor(Cursor.Pointer)
            .styleModifier { property("transition", "border-color 0.18s ease, transform 0.18s ease") }
    }
    Breakpoint.MD {
        Modifier.width(autoLength)
