        Modifier
            .styleModifier {
                property("border-color", GradeMateColors.Primary.toString())
            }
            .styleModifier { property("transform", "translateY(-1px)") }
    }
    focusVisible {
        Modifier.styleModifier {
            property(
                "outline",
                "3px solid ${GradeMateColors.Primary25}"
            )
            property("outline-offset", "2px")
        }
    }
}

