// A shared style for the two real inputs + the textarea, so they look and behave
// consistently: same border/radius/padding at rest, and the same "focus ring"
// (border switches to Primary + a soft outer glow) instead of the browser default.
// A shared style for the two real inputs + the textarea, so they look and behave
// consistently: same border/radius/padding at rest, and the same "focus ring"
// (border switches to Primary + a soft outer glow) instead of the browser default.
val ContactFieldStyle = CssStyle {
    base {
        Modifier
            .fillMaxWidth()
            .fontSize(14.px)
            .color(GradeMateColors.TextPrimary)
            .styleModifier {
                property("border", "1px solid ${GradeMateColors.Border.toRgba()}")
                property("border-radius", "10px")
                property("padding", "10px 14px")
                property("outline", "none")
                property("font-family", "inherit")
                property("box-sizing", "border-box")
                property("background-color", "${GradeMateColors.Surface.toRgba()}")
                property("transition", "border-color 0.15s ease, box-shadow 0.15s ease")
            }
    }
    focusVisible {
        Modifier.styleModifier {
            property("border-color", "${GradeMateColors.Primary.toRgba()}")
            property("box-shadow", "0 0 0 3px ${GradeMateColors.Primary.toRgba(alpha = 0.15f)}")
        }
    }
}

@Composable
fun ContactSection() {
    var name by remember { mutableStateOf("") }
    var email by remember { mutableStateOf("") }
    var message by remember { mutableStateOf("") }
    Box(
        SectionStyle
            .toModifier()
            .id("contact")
            .backgroundColor(GradeMateColors.Surface)
    ) {
        // Div, not Box — Box stacks all direct children into one grid cell, which
        // would collapse the text column and the form card on top of each other.
        Div(
            attrs = ResponsiveRowStyle
                .toModifier()
                .then(SectionInnerStyle.toModifier())
                .toAttrs()
        ) {
            Column(Modifier.fillMaxWidth()) {

                P(
                    EyebrowStyle
                        .toModifier()
                        .margin(0.px)
                        .toAttrs()
                ) {
                    Text("Contact us")
                }

                P(
                    SectionHeadingStyle
                        .toModifier()
                        .margin(top = 10.px, bottom = 12.px)
                        .toAttrs()
                ) {
                    Text("Questions or feedback?")
                }

                P(
                    SectionSubtitleStyle
                        .toModifier()
                        .margin(0.px)
                        .toAttrs()
                ) {
                    Text(
                        "Send a message and we'll get back to you, or reach out directly."
                    )
                }

                Column(
                    Modifier
                        .margin(top = 24.px)
                        .gap(10.px)
                ) {
                    Link(
                        "mailto:lennycodes2000@gmail.com",
                        modifier = Modifier
                            .fontSize(15.px)
                            .color(GradeMateColors.TextPrimary)
                            .styleModifier {
                                property("display", "flex")
                                property("align-items", "center")
                                property("gap", "8px")
                                property("text-decoration", "none")
                            }
                    ) {
                        FaIcon(
                            name = "envelope",
                            style = IconCategory.SOLID,
                            modifier = Modifier.fontSize(15.px)
                        )
                        Text("lennycodes2000@gmail.com")
                    }

                    Link(
                        "https://wa.me/255686777093",
                        modifier = Modifier
                            .fontSize(15.px)
                            .color(GradeMateColors.TextPrimary)
                            .styleModifier {
                                property("display", "flex")
                                property("align-items", "center")
                                property("gap", "8px")
                                property("text-decoration", "none")
                            }
                    ) {
                        FaIcon(
                            name = "whatsapp",
                            style = IconCategory.BRAND,
                            modifier = Modifier.fontSize(15.px)
                        )
                        Text("WhatsApp: +255 686 777 093")
                    }
                }
            }

            // TODO: wire the "action" up to a real form backend (Formspree, your own
            // API endpoint, etc.) — the fields below are real inputs now, but nothing
            Column(
                CardStyle
                    .toModifier()
                    .fillMaxWidth()
                    .gap(14.px)
            ) {
                contactField("Name") {
                    Input(
                        type = InputType.Text,
                        attrs = ContactFieldStyle.toModifier().toAttrs {
                            placeholder("Jane Doe")
                            name("name")
                            value(name)
                            onInput { event -> name = event.value }
                        }
                    )
                }
                contactField("Email") {
                    Input(
                        type = InputType.Email,
                        attrs = ContactFieldStyle.toModifier().toAttrs {
                            placeholder("jane@example.com")
                            name("email")
                            value(email)
                            onInput { event -> email = event.value }
                        }
                    )
                }
                contactField("Message") {
                    // NOTE: some Compose HTML versions take TextArea's value as a named
                    // parameter — TextArea(value = message, attrs = ...) — rather than via
                    // .value() inside attrs like Input. If .value() doesn't resolve here,
                    // switch to that form instead.
                    TextArea(
                        attrs = ContactFieldStyle
                            .toModifier()
                            .height(110.px)
                            .toAttrs {
                                placeholder("How can we help?")
                                name("message")
                                value(message)
                                onInput { event -> message = event.value }
                            }
                    )
                }

                Button(
                    onClick = {
                        val subject = encodeURIComponent("New message from $name via GradeMate")
                        val body = encodeURIComponent("From: $name ($email)\n\n$message")
                        window.location.href = "mailto:lennycodes2000@gmail.com?subject=$subject&body=$body"
                        // Clear the form after handing off to the mail client.
                        name = ""
                        email = ""
                        message = ""
                    },
                    modifier = PrimaryButtonStyle.toModifier()
                ) {
                    Text("Send message")
                }
            }
        }

    // JS's built-in encodeURIComponent, needed so the subject/body survive as valid URL
// query params — spaces, newlines, and punctuation in a raw mailto: link would either
// get silently dropped or break the URL.
    fun encodeURIComponent(str: String): String = js("encodeURIComponent(str)") as String
        }
    }


@Composable
private fun contactField(label: String, field: @Composable () -> Unit) {
    // fillMaxWidth() here matters: without it this Column shrink-wraps to its content
    // (Columns don't stretch children to their own width by default), so the field's
    // own fillMaxWidth() resolves against a narrow, undefined width instead of the
    // full card.
    Column(Modifier.fillMaxWidth().gap(6.px)) {
        P(
            Modifier
                .margin(0.px)
                .fontSize(13.px)
                .fontWeight(FontWeight.Medium)
                .color(GradeMateColors.TextSecondary)
                .toAttrs()
        ) {
            Text(label)
        }
        field()
    }
}